import { Schema } from "effect"

/**
 * The course, decoded at the boundary.
 *
 * `course.json` is generated by tools/app-data.py, so it is external data even
 * though it sits in the repo: a bad generator run must fail here, loudly, at
 * import — not render an empty sidebar. Every class is named for the domain
 * type and carries a description, because these are the shapes the rest of the
 * app reasons about.
 */

export class SourceRef extends Schema.Class<SourceRef>("SourceRef")({
  file: Schema.String,
  start: Schema.Int,
  end: Schema.Int,
  lines: Schema.Array(Schema.String),
}) {}

export class Claim extends Schema.Class<Claim>("Claim")({
  id: Schema.String,
  ref: Schema.Int,
  kind: Schema.String,
  lines: Schema.Array(Schema.Int),
  text: Schema.String,
}) {}

export class Cue extends Schema.Class<Cue>("Cue")({
  claims: Schema.optional(Schema.Array(Schema.String)),
  lines: Schema.optional(Schema.Array(Schema.Int)),
}) {}

export class Beat extends Schema.Class<Beat>("Beat")({
  id: Schema.String,
  text: Schema.String,
  cue: Schema.optional(Cue),
  direction: Schema.optional(Schema.String),
}) {}

export class Figure extends Schema.Class<Figure>("Figure")({
  trace: Schema.String,
  step: Schema.Int,
  note: Schema.optional(Schema.String),
}) {}

export class Lesson extends Schema.Class<Lesson>("Lesson")({
  id: Schema.String,
  stage: Schema.String,
  order: Schema.Int,
  kind: Schema.String,
  title: Schema.String,
  summary: Schema.String,
  minutes: Schema.Int,
  refs: Schema.Array(SourceRef),
  claims: Schema.Array(Claim),
  beats: Schema.Array(Beat),
  figure: Schema.optional(Schema.NullOr(Figure)),
}) {}

export class Stage extends Schema.Class<Stage>("Stage")({
  id: Schema.String,
  name: Schema.String,
  question: Schema.String,
  budget: Schema.Int,
}) {}

export class UOpNode extends Schema.Class<UOpNode>("UOpNode")({
  i: Schema.Int,
  op: Schema.String,
  arg: Schema.String,
  dtype: Schema.String,
  src: Schema.Array(Schema.Int),
}) {}

export class TraceStep extends Schema.Class<TraceStep>("TraceStep")({
  i: Schema.Int,
  caller: Schema.String,
  file: Schema.String,
  line: Schema.Int,
  stage: Schema.String,
  before: Schema.Array(UOpNode),
  after: Schema.Array(UOpNode),
}) {}

export class CourseData extends Schema.Class<CourseData>("CourseData")({
  stages: Schema.Array(Stage),
  lessons: Schema.Array(Lesson),
  traces: Schema.Record(Schema.String, Schema.Array(TraceStep)),
}) {}

export const decodeCourse = Schema.decodeUnknownSync(CourseData)
